// Package pricing resolves on-demand hourly USD prices for cloud instance types
// from a curated, embedded dataset (data.json). The dataset is regenerated by
// cmd/pricing-refresh; the committed values are indicative and should be
// refreshed against provider pricing APIs for authoritative numbers.
package pricing

import (
	_ "embed"
	"encoding/json"
	"log"
	"sort"
	"strings"
	"sync"
)

//go:embed data.json
var dataJSON []byte

// Meta describes the provenance of the embedded dataset.
type Meta struct {
	Source  string `json:"source"`
	Updated string `json:"updated"`
}

type Entry struct {
	InstanceType string
	HourlyUSD    float64
}

var (
	loadOnce sync.Once
	// prices maps canonical provider -> region -> instance type -> USD/hour.
	prices map[string]map[string]map[string]float64
	meta   Meta
)

// canonicalRegions is the region each provider's dataset is primarily curated
// for. Lookups that miss the requested region fall back to this region so a
// benchmark run in an uncurated region still resolves a (best-effort) price.
var canonicalRegions = map[string]string{
	"aws":   "us-west-2",
	"gcp":   "us-central1",
	"azure": "eastus",
}

func load() {
	loadOnce.Do(func() {
		var raw map[string]json.RawMessage
		if err := json.Unmarshal(dataJSON, &raw); err != nil {
			log.Printf("pricing: parsing embedded data.json: %v", err)
			return
		}
		prices = make(map[string]map[string]map[string]float64, len(raw))
		for key, val := range raw {
			if key == "_meta" {
				if err := json.Unmarshal(val, &meta); err != nil {
					log.Printf("pricing: parsing _meta: %v", err)
				}
				continue
			}
			var byRegion map[string]map[string]float64
			if err := json.Unmarshal(val, &byRegion); err != nil {
				log.Printf("pricing: parsing provider block %q: %v", key, err)
				continue
			}
			prices[key] = byRegion
		}
	})
}

// Source returns the provenance metadata for the embedded dataset.
func Source() Meta {
	load()
	return meta
}

// canonicalProvider maps K8s providers to the VM provider whose instance types
// (and therefore prices) they share. EKS runs EC2 types, GKE runs GCP machine
// types, AKS runs Azure VM sizes.
func canonicalProvider(provider string) string {
	switch provider {
	case "eks":
		return "aws"
	case "gke":
		return "gcp"
	case "aks":
		return "azure"
	default:
		return provider
	}
}

// canonicalRegion normalizes a region string. GCP zones (e.g. "us-central1-a")
// collapse to their region ("us-central1"); a single-character final segment is
// treated as a zone suffix. Other providers pass through unchanged.
func canonicalRegion(provider, region string) string {
	if provider != "gcp" {
		return region
	}
	if i := strings.LastIndex(region, "-"); i > 0 && len(region[i+1:]) == 1 {
		return region[:i]
	}
	return region
}

// Lookup returns the on-demand hourly USD price for the given provider, region,
// and instance type. The second return value is false when no price is known.
func Lookup(provider, region, instanceType string) (float64, bool) {
	load()

	cp := canonicalProvider(provider)
	byRegion, ok := prices[cp]
	if !ok {
		return 0, false
	}

	r := canonicalRegion(cp, region)
	if price, ok := byRegion[r][instanceType]; ok {
		return price, true
	}

	if canon := canonicalRegions[cp]; canon != "" && canon != r {
		if price, ok := byRegion[canon][instanceType]; ok {
			log.Printf("pricing: %s %s not priced in %q; using canonical region %q", cp, instanceType, r, canon)
			return price, true
		}
	}

	return 0, false
}

// List returns the checked-in prices available for a provider and region.
// Kubernetes providers use their underlying VM catalog. When a requested
// region is not curated, the canonical region is used as an explicitly
// best-effort local catalog.
func List(provider, region string) ([]Entry, Meta) {
	load()

	cp := canonicalProvider(provider)
	byRegion := prices[cp]
	selectedRegion := canonicalRegion(cp, region)
	byType := byRegion[selectedRegion]
	if len(byType) == 0 {
		selectedRegion = canonicalRegions[cp]
		byType = byRegion[selectedRegion]
	}

	entries := make([]Entry, 0, len(byType))
	for instanceType, hourlyUSD := range byType {
		entries = append(entries, Entry{InstanceType: instanceType, HourlyUSD: hourlyUSD})
	}
	sort.Slice(entries, func(i, j int) bool {
		return entries[i].InstanceType < entries[j].InstanceType
	})
	return entries, meta
}
